<section class="panel portal-profile" id="profile"><div class="panel-head"><div><h2>My profile</h2><p>Update your own contact and work-location details</p></div><a href="<?= url('account/password') ?>">Change password</a></div><form class="mini-form" method="post" action="<?= url('portal/staff/profile') ?>"><?= csrf_field() ?><div class="form-grid"><label>Full name<input name="name" value="<?= e(auth()['name']) ?>" required maxlength="150"></label><label>Phone<input name="phone" value="<?= e(auth()['phone']) ?>" required maxlength="30"></label><label>Emergency contact<input name="emergency_contact" value="<?= e($staff['emergency_contact']) ?>" maxlength="30"></label><label>Work location<input name="work_location" value="<?= e($staff['work_location']) ?>" maxlength="150"></label><label class="wide">Address<textarea name="address" rows="3"><?= e($staff['address']) ?></textarea></label></div><button class="button button-primary button-sm">Save my profile</button></form></section>
